  if (devServers === null) {
    await bringUpContainers({ instance, options, steps, renderedRealm, seededMarker });
    await printEndpoints(instance, proxyPort);
    console.log('\nDev servers not started (--detach). Run `just serve` to start them.');
    return 0;
  } else {
    // From here until `finishDevServers` the dev servers are running unattended, for minutes: a
    // failed container step or a Ctrl-C in the middle of the image build must stop them, or they
    // hold their allocated ports and outlive this process — and the next `just up` would either
    // allocate different ones or fail to bind these.
    const outcome = await superviseStartup(devServers, async () => {
      await bringUpContainers({ instance, options, steps, renderedRealm, seededMarker });
      // The URL table waits for this. Printed any earlier — as it used to be — every link in it is a
      // connection refused for the minute or two the dev servers take to build, and the last thing
      // left on screen is the dev server's own banner advertising a localhost URL that the backend's
      // CORS list rejects.
      return await awaitDevServersReady({ handle: devServers });
    });

    if (outcome === INTERRUPTED) {
      // Not torn down: whatever containers already started are left to the next `just up`, which
      // converges on them rather than starting over.
      console.log(
        '\nInterrupted — the dev servers are stopped. Containers that had already started are still ' +
          'running;\n`just up` carries on from there, `just down` stops them.',
      );
      return 130;
    } else {
      if (anyExited(outcome)) {
        // Its crash report is already on screen, and `finishDevServers` below turns it into the exit
        // code straight away. A URL table and "running" now would announce a success that is not.
      } else {
        await printEndpoints(instance, proxyPort, notAnswering(outcome));
        console.log(
          '\nDev servers are running — Ctrl-C stops all of them. Their output is captured, not ' +
            'printed;\n`just logs app` (or cms/boards) follows one.',
        );
      }
      // If one dev server dies on its own, `just up` must not sit there looking healthy with two of
      // three running, nor exit 0 as if it had been a clean Ctrl-C — `finishDevServers` races the
      // crash against the signals and reports whichever one actually happened.
      const exitCode = await finishDevServers({ handle: devServers });
      console.log(stoppedMessage());
      return exitCode;
    }
  }
