/**
 * Everything docker has to do, in the one order that works: create (so the network exists) →
 * attach the proxy (so the public names resolve inside it) → start and wait for health → seed.
 * See `composeCreateArgs` for why creating and starting have to be separate calls.
 */
async function bringUpContainers({ instance, options, steps, renderedRealm, seededMarker }) {
  await runStep({
    pending: 'Building images and creating containers',
    done: 'Built images and created containers',
    logFile: logFileFor(instance, 'containers-create'),
    run: (logFile) => composeCaptured(instance, composeCreateArgs(options), { logFile }),
  });
  await attachInstance({ repoRoot: REPO_ROOT, instance, exec: run });
  await startAndWait(instance, options);

  if (steps.recordRealmHash) {
    // Keycloak's database was either just wiped (`--fresh`) or has never finished a `just up`
    // before — in both cases the container that just went healthy in `startAndWait` above imported
    // the realm we rendered for real, so this is the one moment recording it is actually true. This
    // runs whether or not the *app's* sample data gets seeded below: the realm import is Keycloak's
    // business, entirely independent of that.
    writeRealmHash(instance, renderedRealm);
  }

  await SEEDING[steps.seeding]({ instance, seededMarker });
}

const SEEDING = {
  seed: ({ instance, seededMarker }) => runSeeder(instance, seededMarker),
  reseed: ({ instance, seededMarker }) => reseedOrWarn(() => runSeeder(instance, seededMarker)),
  'leave-unseeded': async () => {
    console.log(
      '\nSkipping seeding (--no-seed). The database is not seeded yet — run `just up` ' +
        '(without --no-seed) to seed it.',
    );
  },
  'leave-unchanged': async () => {
    console.log('\nSample data left unchanged. `just up --seed` re-seeds it.');
  },
};

/**
 * --force-recreate because this is a one-shot job, not a service: a leftover container from an
 * earlier run holds that run's network id, and after `just reset` recreated the network compose
 * would try to *start* the stale one and fail with "network ... not found". Observed in a real
 * cold-start cycle. Recreating a container that is meant to run once and exit costs nothing.
 */
async function runSeeder(instance, seededMarker) {
  await runStep({
    pending: 'Seeding sample data',
    done: 'Seeded sample data',
    logFile: logFileFor(instance, 'seed'),
    run: (logFile) => composeCaptured(instance, seedArgs(), { logFile }),
  });
  writeFileSync(seededMarker, `${new Date().toISOString()}\n`);
}

/**
 * The endpoints a developer came for. Printed once the things behind them can actually answer, which
 * is why this is a function rather than a straight line through `main`: `--detach` reaches it as
 * soon as the containers are up, while a normal run has to wait for the dev servers first.
 */
async function printEndpoints(instance, proxyPort, notAnsweringNames = new Set()) {
  console.log(`\nURLs\n${urlTable(instance, proxyPort, notAnsweringNames)}`);
  const dbPort = await postgresHostPort(instance, run);
  if (dbPort === null) {
    console.log('\nPostgres\n  unavailable');
  } else {
    console.log(`\nPostgres\n${postgresHint(dbPort)}`);
  }
}

async function askTerminal(question, fallback) {
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  try {
    return await rl.question(`${question} [${fallback}]: `);
  } finally {
    rl.close();
  }
}

